'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let user=null,csrf='',currentPage=location.hash.slice(1)||'overview',authMode='login',health=null,devices=[],contacts=[],incidents=[],events=[],outbox=[],selectedDevice='',refreshTimer=null,toastTimer=null;
const labels={DISABLED:'Proteção desativada',ACTIVE:'Proteção ativa',EMERGENCY:'Emergência detectada',LOST:'Dispositivo perdido',RECOVERING:'Recuperação em andamento',RESOLVED:'Emergência encerrada'};
const commandLabels={LOCK:'Bloquear tela',LOST:'Ativar modo perdido',RECOVER:'Encerrar estado de proteção',ALARM:'Acionar alarme',STOP_ALARM:'Interromper alarme'};
const statusLabels={QUEUED:'Na fila',PENDING:'Pendente',SENT:'Enviado',DELIVERED:'Entregue',ACKNOWLEDGED:'Confirmado pelo dispositivo',EXECUTED:'Executado e confirmado',SUCCEEDED:'Confirmado',LEASED:'Recebido pelo cliente; aguardando resultado',FAILED:'Falhou',EXPIRED:'Expirado',CANCELLED:'Cancelado'};
const date=v=>v?new Date(v).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'Não disponível';
const empty=(title,text,button='')=>`<div class="empty"><h3>${esc(title)}</h3><p>${esc(text)}</p>${button}</div>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
async function api(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(csrf&&options.method&&options.method!=='GET')headers['x-csrf-token']=csrf;let r;try{r=await fetch(path,{credentials:'same-origin',...options,headers,body:options.body===undefined?undefined:JSON.stringify(options.body)})}catch{throw new Error('Não foi possível conectar ao servidor. Verifique a conexão e tente novamente.')}let data;try{data=await r.json()}catch{throw new Error('Resposta inválida do servidor.')}if(!r.ok){if(r.status===401&&user){user=null;csrf='';showAuth();}throw new Error(data.error||`A solicitação falhou (${r.status}).`)}return data}
function message(text,isError=false){const el=$('#authMessage');el.textContent=text;el.className='message'+(isError?' error':'')}
function modal(html){$('#dialogContent').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
$('#closeDialog').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog'))$('#dialog').close()};
function buttonBusy(button,busy,label){if(!button)return;button.disabled=busy;if(label)button.textContent=label;}
function showAuth(){$('#menuToggle').classList.add('hidden');closeMenu();clearInterval(refreshTimer);$('#auth').classList.remove('hidden');$('#workspace').classList.add('hidden');$('#logout').classList.add('hidden');$('#devDelivery').classList.add('hidden');renderAuth()}
function renderAuth(){const mode=authMode;$('#authMessage').classList.add('hidden');$$('#authTabs button').forEach(b=>b.classList.toggle('selected',b.dataset.auth===mode));const html=mode==='register'?`<div class="eyebrow">UM NOVO COMEÇO</div><h2 style="margin-top:15px">Crie seu acesso.</h2><p class="fine">Use dados de teste. A confirmação de e-mail no desenvolvimento acontece pela caixa de entrega local.</p><form id="registerForm"><label for="registerName">Seu nome</label><input id="registerName" autocomplete="name" required maxlength="80"><label for="registerEmail">E-mail</label><input id="registerEmail" type="email" autocomplete="email" required maxlength="254"><label for="registerPassword">Senha</label><input id="registerPassword" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><p class="form-note">Mínimo de 12 caracteres. Não use uma senha de outra conta.</p><div class="actions"><button class="primary full">Criar conta de teste ↗</button></div></form>`:mode==='recover'?`<div class="eyebrow">VOLTE COM CONFIANÇA</div><h2 style="margin-top:15px">Recupere seu acesso.</h2><p class="fine">Solicite um token de uso único. No ambiente local, consulte a caixa de entrega após entrar em uma sessão autorizada, ou use o token disponibilizado pelo operador de desenvolvimento.</p><form id="requestResetForm"><label for="resetEmail">E-mail da conta</label><input id="resetEmail" type="email" autocomplete="email" required><div class="actions"><button class="primary full">Solicitar recuperação</button></div></form><details style="margin-top:22px"><summary>Já tenho o token</summary><form id="resetForm"><label for="resetToken">Token de recuperação</label><input id="resetToken" autocomplete="off" required><label for="newPassword">Nova senha</label><input id="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><div class="actions"><button class="outline full">Redefinir senha</button></div></form></details>`:`<div class="eyebrow">BOM TER VOCÊ DE VOLTA</div><h2 style="margin-top:15px">Seu acesso seguro.</h2><p class="fine">Sua conta, seus dispositivos e o histórico das ações autorizadas.</p><form id="loginForm"><label for="loginEmail">E-mail</label><input id="loginEmail" type="email" autocomplete="username" required><label for="loginPassword">Senha</label><input id="loginPassword" type="password" autocomplete="current-password" required><div class="actions"><button class="primary full">Entrar no painel ↗</button></div></form>`;$('#authContent').innerHTML=html;
if($('#loginForm'))$('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;buttonBusy(b,true);try{await api('/api/auth/login',{method:'POST',body:{email:$('#loginEmail').value.trim(),password:$('#loginPassword').value}});await loadSession();toast('Sessão autenticada.')}catch(error){message(error.message,true)}finally{buttonBusy(b,false)}};
if($('#registerForm'))$('#registerForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;buttonBusy(b,true);const email=$('#registerEmail').value.trim(),password=$('#registerPassword').value;try{await api('/api/auth/register',{method:'POST',body:{name:$('#registerName').value.trim(),email,password}});await api('/api/auth/login',{method:'POST',body:{email,password}});await loadSession();toast('Conta criada. Confirme o e-mail pela entrega local antes de cadastrar um aparelho.')}catch(error){message(error.message,true)}finally{buttonBusy(b,false)}};
if($('#requestResetForm'))$('#requestResetForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;buttonBusy(b,true);try{await api('/api/auth/request-reset',{method:'POST',body:{email:$('#resetEmail').value.trim()}});message('Solicitação processada. Se a conta existir, o backend gerará uma entrega pelo transporte configurado.')}catch(error){message(error.message,true)}finally{buttonBusy(b,false)}};
if($('#resetForm'))$('#resetForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;buttonBusy(b,true);try{await api('/api/auth/reset',{method:'POST',body:{token:$('#resetToken').value.trim(),password:$('#newPassword').value}});authMode='login';renderAuth();message('Senha redefinida. Entre novamente.')}catch(error){message(error.message,true)}finally{buttonBusy(b,false)}};
}
$('#authTabs').onclick=e=>{const b=e.target.closest('[data-auth]');if(b){authMode=b.dataset.auth;renderAuth()}};
async function loadSession(){try{const data=await api('/api/auth/me');user=data.user;csrf=data.csrfToken||'';if(!user)return showAuth();$('#auth').classList.add('hidden');$('#workspace').classList.remove('hidden');$('#logout').classList.remove('hidden');$('#menuToggle').classList.remove('hidden');$('#accountName').textContent=user.name||user.email;renderVerification();await refreshData();await loadOutbox();clearInterval(refreshTimer);refreshTimer=setInterval(()=>{if(user&&!document.hidden&&!$('#dialog').open)refreshData(false).catch(()=>{})},20000)}catch(error){showAuth();if(!/autentic|sessão|Unauthorized/i.test(error.message))message(error.message,true)}}
function isVerified(){return Boolean(user?.emailVerified||user?.emailVerifiedAt)}
function renderVerification(){const el=$('#verificationBanner');if(isVerified()){el.classList.add('hidden');return}el.classList.remove('hidden');el.innerHTML=`<b>Confirme seu e-mail para cadastrar dispositivos e enviar comandos.</b><br>No desenvolvimento local, o token fica na caixa de entrega abaixo.<div><button class="outline small" data-action="requestEmail">Gerar nova confirmação</button><button class="outline small" data-action="verifyEmail">Inserir token de confirmação</button></div>`}
async function refreshData(showLoading=true){if(!user)return;if(showLoading)$('#content').setAttribute('aria-busy','true');if(showLoading)$('#content').innerHTML='<p class="loading">Atualizando seus dados…</p>';const results=await Promise.allSettled([api('/api/devices'),api('/api/contacts'),api('/api/incidents'),api('/api/audit')]);if(results[0].status==='fulfilled')devices=results[0].value.devices||[];else if(showLoading)toast(results[0].reason.message);if(results[1].status==='fulfilled')contacts=results[1].value.contacts||[];if(results[2].status==='fulfilled')incidents=results[2].value.incidents||[];if(results[3].status==='fulfilled')events=results[3].value.events||[];if(!selectedDevice||!devices.some(d=>d.id===selectedDevice))selectedDevice=devices[0]?.id||'';await renderPage();}
$('#refresh').onclick=()=>refreshData().then(()=>loadOutbox()).catch(e=>toast(e.message));
$('#logout').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST',body:{}});user=null;csrf='';devices=[];contacts=[];incidents=[];events=[];outbox=[];showAuth();toast('Sessão encerrada.')}catch(error){toast(error.message)}};
$('#navigation').onclick=e=>{const b=e.target.closest('[data-page]');if(b){currentPage=b.dataset.page;closeMenu();history.replaceState(null,'','#'+currentPage);renderPage().catch(error=>toast(error.message))}};
function deviceState(d){return labels[d.state||d.status]||d.state||d.status||'Não informado'}
function isOnline(d){if(typeof d.online==='boolean')return d.online;if(typeof d.isOnline==='boolean')return d.isOnline;const t=d.lastSeenAt||d.lastSeen;return Boolean(t&&Date.now()-new Date(t).getTime()<120000)}
function deviceName(id){return devices.find(d=>d.id===id)?.name||'Dispositivo'}
function tag(status){return `<span class="state-tag ${['EMERGENCY','LOST','FAILED'].includes(status)?'alert':''}">${esc(labels[status]||statusLabels[status]||status||'Sem informação')}</span>`}
function deviceCard(d){const online=isOnline(d);return `<article class="device"><div class="row"><div><h3>${esc(d.name)}</h3><span class="fine muted">${esc(d.platform||'ANDROID')} · ID ${esc(d.id)}</span></div><span class="pill ${online?'good':'warn'}">${online?'Online':'Offline / sem sinal recente'}</span></div><div class="device-meta"><div><b>Proteção</b><span>${esc(deviceState(d))}</span></div><div><b>Última comunicação</b><span>${esc(date(d.lastSeenAt||d.lastSeen))}</span></div><div><b>Administração Android</b><span>${(d.adminActive===true||d.capabilities?.deviceAdmin===true||d.capabilities?.adminActive===true)?'Autorização informada pelo aparelho':d.adminActive===false?'Ainda não autorizada':'Aguardando informação do aparelho'}</span></div></div><div class="actions"><button class="primary small" data-command="LOCK" data-device="${esc(d.id)}">Bloquear tela ↗</button><button class="outline small" data-command="LOST" data-device="${esc(d.id)}">Modo perdido</button><button class="outline small" data-device-location="${esc(d.id)}">Ver localização</button><button class="outline small" data-device-detail="${esc(d.id)}">Detalhes</button><button class="quiet" data-disconnect="${esc(d.id)}">Desconectar</button></div></article>`}
function incidentRows(list=incidents){return list.length?list.map(i=>`<div class="activity"><div><strong>${esc(i.type||i.title||'Incidente')}</strong><span>${esc(deviceName(i.deviceId))}</span><br><button class="quiet" data-incident="${esc(i.id)}">Ver detalhes ↗</button>${i.details?`<br><small>${esc(typeof i.details==='string'?i.details:JSON.stringify(i.details))}</small>`:''}</div><div>${tag(i.state||i.status)}<br><small>${esc(date(i.createdAt||i.timestamp))}</small></div></div>`).join(''):empty('Nenhum incidente registrado.','Os eventos serão exibidos quando o Android enviar uma ativação real. Não há incidentes fictícios neste painel.')}
function auditRows(list=events){return list.length?list.map(e=>`<div class="activity"><div><strong>${esc(e.action||e.type||'Ação registrada')}</strong><small>${esc(typeof e.details==='string'?e.details:JSON.stringify(e.details||{}))}</small></div><small>${esc(date(e.createdAt||e.timestamp))}</small></div>`).join(''):empty('Nenhuma ação registrada.','O backend registrará acessos e operações autenticadas.')}
function selectDeviceHTML(){return `<label for="locationDevice">Dispositivo autorizado</label><select id="locationDevice" class="location-select">${devices.map(d=>`<option value="${esc(d.id)}" ${d.id===selectedDevice?'selected':''}>${esc(d.name)}</option>`).join('')}</select>`}
async function renderPage(){if(!user)return;const page=currentPage;$$('#navigation button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const titles={overview:'Seu cuidado, em foco.',devices:'Aparelhos sob seu controle.',locations:'A última posição disponível.',protection:'Proteção com clareza.',voice:'Sua voz, com privacidade.',triggers:'Atalhos para agir.',lost:'Encontre um ponto de apoio.',notifications:'O que precisa de atenção.',profile:'Seus dados, seu controle.',help:'Orientação em cada etapa.',incidents:'Cada evento, registrado.',contacts:'Sua rede de confiança.',commands:'Ações com rastreabilidade.',recovery:'Retome o controle.',security:'Sua identidade, preservada.',subscription:'Uma estrutura para continuar.'};$('#pageTitle').textContent=titles[page]||titles.overview;$('#pageEyebrow').textContent=health?.mode==='development'?'AMBIENTE LOCAL DE DESENVOLVIMENTO':'PAINEL DE PROTEÇÃO';let html='';
if(page==='overview')html=`<div class="grid-three"><div class="metric"><div class="eyebrow">DISPOSITIVOS</div><strong>${devices.length}</strong><span>Vinculados à sua conta</span></div><div class="metric"><div class="eyebrow">ONLINE</div><strong>${devices.filter(isOnline).length}</strong><span>Comunicação recente</span></div><div class="metric"><div class="eyebrow">INCIDENTES</div><strong>${incidents.length}</strong><span>Eventos persistidos</span></div></div><section class="section-card"><div class="section-heading"><h3>Seus dispositivos.</h3><button class="outline small" data-action="registerDevice">Cadastrar Android ↗</button></div><div class="device-list">${devices.length?devices.slice(0,2).map(deviceCard).join(''):empty('Seu primeiro dispositivo.','Cadastre um aparelho e utilize a credencial fornecida no aplicativo Android nativo. O bloqueio exige a administração autorizada no aparelho.')}</div></section><section class="section-card"><h3>Últimos incidentes.</h3>${incidentRows(incidents.slice(0,4))}</section>`;
if(page==='devices')html=`<div class="section-heading"><p class="fine">A credencial de cada aparelho é individual. Desconectar revoga o acesso à API.</p><button class="primary small" data-action="registerDevice">Cadastrar Android ↗</button></div><div class="device-list">${devices.length?devices.map(deviceCard).join(''):empty('Nenhum dispositivo cadastrado.','Confirme seu e-mail e cadastre o primeiro Android.')}</div><div class="flow-note">O painel não pode executar um bloqueio por conta própria: ele cria um comando autenticado. O aparelho precisa estar online e autorizar o recurso nativo. Confira o resultado na área de Comandos.</div>`;
if(page==='locations')html=devices.length?`${selectDeviceHTML()}<div id="locationContent" class="loading">Buscando posição registrada…</div>`:empty('Nenhuma localização disponível.','Cadastre e conecte um Android. A localização só aparece depois da permissão e do envio pelo aparelho.');
if(page==='incidents')html=`<div class="filter-bar"><label for="incidentSearch">Buscar evento<input id="incidentSearch" type="search" placeholder="Tipo ou dispositivo"></label><label for="incidentState">Estado<select id="incidentState"><option value="">Todos</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label></div><section class="section-card" style="margin-top:0"><h3>Histórico de proteção.</h3><div id="incidentResults">${incidentRows()}</div></section>`;
if(page==='contacts')html=`<div class="split"><section class="section-card" style="margin-top:0"><h3>Pessoas autorizadas.</h3>${contacts.length?contacts.map(c=>`<div class="activity"><div><strong>${esc(c.name)}</strong><span>${esc(c.phone)}</span><br><small>${esc(c.email||'Sem e-mail cadastrado')}</small><br><small>Alertas: ${c.allowAlerts?'autorizados':'não autorizados'} · E-mail ${c.emailVerified?'confirmado':'pendente'}</small></div><div><span class="pill ${c.verified||c.phoneVerified||c.phoneVerifiedAt?'good':'warn'}">${c.verified||c.phoneVerified||c.phoneVerifiedAt?'Número confirmado':'Número pendente'}</span><div class="actions"><button class="outline small" data-verify-contact="${esc(c.id)}">Validar número</button>${c.email?`<button type="button" class="outline small" data-verify-contact-email="${esc(c.id)}">Validar e-mail</button>`:''}<button class="outline small" data-edit-contact="${esc(c.id)}" type="button">Editar</button><button class="quiet" data-delete-contact="${esc(c.id)}" type="button">Remover</button></div></div></div>`).join(''):empty('Nenhum contato cadastrado.','Adicione uma pessoa de confiança e confirme o número antes de utilizar alertas.')}</section><section class="section-card" style="margin-top:0"><h3>Adicionar contato.</h3><form id="contactForm" class="contact-form"><label for="contactName">Nome</label><input id="contactName" required maxlength="80"><label for="contactPhone">Telefone com código do país</label><input id="contactPhone" type="tel" placeholder="+5581999999999" pattern="[+][1-9][0-9]{7,14}" required maxlength="16"><label for="contactEmail">E-mail para alertas (opcional)</label><input id="contactEmail" type="email" maxlength="254"><label class="checkbox-label"><input id="allowAlerts" type="checkbox">Autorizo os alertas para este contato e confirmo que ele concorda em receber essas informações.</label><p class="fine">Na configuração local, as entregas ficam na caixa de desenvolvimento. Não há envio real de e-mail ou SMS.</p><div class="actions"><button class="primary">Salvar contato</button></div></form></section></div>`;
if(page==='commands')html=devices.length?`${selectDeviceHTML()}<div class="section-card"><h3>Solicitar uma ação.</h3><p class="fine">Cada ação exige confirmação de senha. Estar na fila não significa que a operação foi executada pelo Android.</p><div class="actions">${Object.entries(commandLabels).map(([type,label])=>`<button class="${type==='LOCK'?'primary':'outline'} small" data-command="${type}" data-device="${esc(selectedDevice)}">${label}</button>`).join('')}</div></div><section class="section-card"><h3>Solicitações e confirmações.</h3><div id="commandsContent" class="loading">Buscando comandos…</div></section>`:empty('Nenhum aparelho vinculado.','Cadastre um dispositivo para enviar ações autenticadas.');
if(page==='recovery')html=`<section class="section-card" style="margin-top:0"><h3>Recuperação em camadas.</h3><p>Entre em uma sessão autenticada, confirme sua senha e encerre o estado de proteção do SENTINELA. Essa ação não remove o PIN, a senha ou a biometria nativa do Android.</p><ul class="checklist"><li>E-mail da conta ${isVerified()?'confirmado':'ainda não confirmado'}.</li><li>Operação remota com confirmação da senha atual e registro de auditoria.</li><li>O aparelho confirma a aplicação da ação quando estiver conectado.</li><li>A voz não autoriza recuperação. Biometria e aprovação de contato só poderão ser utilizadas quando houver implementação nativa validada.</li></ul><div class="actions">${devices.map(d=>`<button class="primary" data-command="RECOVER" data-device="${esc(d.id)}">Recuperar ${esc(d.name)} ↗</button>`).join('')||'<span class="fine">Cadastre um Android para habilitar a solicitação.</span>'}</div></section><section class="section-card"><h3>Recuperação da conta.</h3><p class="fine">Uma nova solicitação gera um token de uso único. A senha do sistema operacional do telefone permanece inalterada.</p><button class="outline small" data-action="resetOwnAccount">Solicitar redefinição da senha da conta</button></section>`;
if(page==='security')html=`<div class="split"><section class="section-card" style="margin-top:0"><h3>Sessões autenticadas.</h3><div id="sessionsContent" class="loading">Consultando sessões…</div></section><section class="section-card" style="margin-top:0"><h3>Retenção de localização.</h3><form id="settingsForm" class="settings-form"><label for="retentionDays">Excluir posições mais antigas que</label><select id="retentionDays"><option value="1">1 dia</option><option value="7">7 dias</option><option value="30">30 dias</option><option value="90">90 dias</option></select><p class="fine">A retenção limita o histórico armazenado. A exclusão de posições pode ser solicitada para cada aparelho abaixo.</p><div class="actions"><button class="primary small">Salvar preferência</button></div></form><div class="actions">${devices.map(d=>`<button class="outline small" data-delete-locations="${esc(d.id)}">Excluir posições de ${esc(d.name)}</button>`).join('')}</div></section></div><section class="section-card"><h3>Telefone principal.</h3><p class="fine">${esc(user.phone||'Nenhum telefone cadastrado')} · ${user.phoneVerified?'Confirmado no ambiente local':'Ainda não confirmado'}</p><div class="actions"><button class="outline small" data-action="primaryPhone">Cadastrar / confirmar telefone</button></div></section><section class="section-card"><h3>Histórico de acessos e ações.</h3>${auditRows()}</section>`;
if(page==='subscription')html='<div class="loading">Consultando estrutura de assinatura…</div>';
if(!html)html=extraPage(page);$('#content').innerHTML=html;$('#content').setAttribute('aria-busy','false');wireForms();wireExtra();
if(page==='locations'&&devices.length){$('#locationDevice').onchange=()=>{selectedDevice=$('#locationDevice').value;loadLocations()};await loadLocations()}
if(page==='commands'&&devices.length){$('#locationDevice').onchange=()=>{selectedDevice=$('#locationDevice').value;renderPage()};await loadCommands()}
if(page==='profile')await loadProfile();if(page==='notifications')await loadNotifications();if(page==='security')await loadSecurity();if(page==='subscription')await loadSubscription();
}
async function loadLocations(){const id=selectedDevice;try{const result=await api(`/api/devices/${encodeURIComponent(id)}/locations`);if(currentPage!=='locations'||id!==selectedDevice)return;const positions=result.locations||[],last=positions[0];if(!last){$('#locationContent').innerHTML=empty('Nenhuma posição recebida.','Abra o Android cadastrado, autorize a localização e solicite o envio. O painel não coleta a localização deste navegador.');return}$('#locationContent').innerHTML=`<div class="map"><p>REPRESENTAÇÃO ESQUEMÁTICA · SEM MAPA EXTERNO</p><span class="point"></span><div class="coordinates"><span>Lat. ${esc(Number(last.latitude).toFixed(6))}</span><span>Long. ${esc(Number(last.longitude).toFixed(6))}</span></div></div><p class="map-caption">Última posição registrada: ${esc(date(last.capturedAt||last.createdAt))} · Precisão estimada: ${esc(Math.round(last.accuracy||0))} m. O ponto central representa a coordenada acima; esta grade não é um mapa geográfico e não indica movimento.</p><div class="flow-note">Se o dispositivo estiver desligado ou sem conexão, esta será apenas a última posição recebida. Buscar da Apple e Find Hub do Google são serviços nativos independentes, disponíveis conforme modelo e configuração.</div><div class="section-card"><h3>Histórico autorizado.</h3><div class="table-scroll"><table><thead><tr><th>Capturada em</th><th>Latitude</th><th>Longitude</th><th>Precisão</th></tr></thead><tbody>${positions.map(p=>`<tr><td>${esc(date(p.capturedAt||p.createdAt))}</td><td>${esc(p.latitude)}</td><td>${esc(p.longitude)}</td><td>${esc(Math.round(p.accuracy||0))} m</td></tr>`).join('')}</tbody></table></div></div>`}catch(error){if($('#locationContent'))$('#locationContent').innerHTML=empty('Não foi possível carregar.',error.message)}}
async function loadCommands(){const id=selectedDevice;try{const result=await api(`/api/devices/${encodeURIComponent(id)}/commands`);if(currentPage!=='commands'||selectedDevice!==id)return;const commands=result.commands||[];$('#commandsContent').innerHTML=commands.length?commands.map(c=>`<div class="activity"><div><strong>${esc(commandLabels[c.type]||c.type)}</strong><small>${esc(date(c.createdAt))}</small>${c.result||c.error?`<br><small>${esc(typeof c.result==='string'?c.result:JSON.stringify(c.result||c.error))}</small>`:''}</div><div>${tag(c.status)}<br><small>${(c.acknowledgedAt||c.ackedAt)?'Confirmação: '+esc(date(c.acknowledgedAt||c.ackedAt)):c.completedAt?'Conclusão: '+esc(date(c.completedAt)):'Aguardando confirmação do aparelho'}</small></div></div>`).join(''):empty('Nenhum comando solicitado.','As operações aguardam confirmação do aparelho e podem expirar se ele estiver offline.')}catch(error){if($('#commandsContent'))$('#commandsContent').innerHTML=empty('Histórico indisponível.',error.message)}}
async function loadSecurity(){const results=await Promise.allSettled([api('/api/auth/sessions'),api('/api/settings')]);if(currentPage!=='security')return;if(results[0].status==='fulfilled'){const list=results[0].value.sessions||[];$('#sessionsContent').innerHTML=list.length?list.map(s=>`<div class="activity"><div><strong>${s.current?'Sessão atual':'Sessão autenticada'}</strong><small>${esc(s.userAgent||s.agent||s.device||'Cliente não informado')}<br>Criada: ${esc(date(s.createdAt))}<br>Último uso: ${esc(date(s.lastUsedAt||s.lastSeenAt||s.lastSeen))}</small></div><button class="outline small" data-revoke-session="${esc(s.id)}">Encerrar</button></div>`).join(''):empty('Nenhuma sessão encontrada.','Atualize para consultar o servidor.')}else $('#sessionsContent').innerHTML=empty('Sessões indisponíveis.',results[0].reason.message);if(results[1].status==='fulfilled'){const settings=results[1].value.settings||results[1].value;$('#retentionDays').value=String(settings.retentionDays||30)}}
async function loadSubscription(){try{const r=await api('/api/subscription');if(currentPage!=='subscription')return;const subscription=r.subscription,plans=r.plans||[];$('#content').innerHTML=`<div class="notice">Estrutura de assinatura preparada. Não existe cobrança ativa neste ambiente. O vencimento de um plano não deve encerrar uma emergência nem desbloquear o aparelho.</div><section class="section-card"><h3>Sua assinatura.</h3><p>${subscription?`${esc(subscription.plan?.name||({ESSENTIAL:'Essencial',PLUS:'Proteção Plus',FAMILY:'Família'}[subscription.plan])||subscription.planName||subscription.planId||'Plano cadastrado')} · ${esc(subscription.status||'Sem status')}`:'Nenhuma assinatura comercial ativa.'}</p><p class="fine">Renovação, cancelamento e pagamentos dependem da integração autorizada de billing. Google Play Billing e regras de plataforma devem ser avaliados antes da venda.</p><div class="actions"><button class="outline small" data-action="cancelPlan">Registrar cancelamento</button></div></section><div class="grid-three" style="margin-top:22px">${plans.map(p=>`<article class="metric"><div class="eyebrow">${esc(p.id||p.code)}</div><h3 style="margin-top:16px">${esc(p.name)}</h3><p class="fine">Até ${esc(p.deviceLimit||p.maxDevices||1)} dispositivo(s)</p><span>Preço em definição · Sem contratação</span>${health?.mode==='development'?`<div class="actions"><button class="outline small" data-dev-plan="${esc(p.id)}">Testar permissões do plano</button></div>`:''}</article>`).join('')}</div>`}catch(error){$('#content').innerHTML=empty('Assinatura indisponível.',error.message)}}
function wireForms(){if($('#contactForm'))$('#contactForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;buttonBusy(b,true);try{await api('/api/contacts',{method:'POST',body:{name:$('#contactName').value.trim(),phone:$('#contactPhone').value.trim(),email:$('#contactEmail').value.trim()||undefined,allowAlerts:$('#allowAlerts').checked}});toast('Contato cadastrado. Confirme o número antes de utilizar os alertas.');await refreshData()}catch(error){toast(error.message)}finally{buttonBusy(b,false)}};if($('#settingsForm'))$('#settingsForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;buttonBusy(b,true);try{await api('/api/settings',{method:'PATCH',body:{retentionDays:Number($('#retentionDays').value)}});toast('Preferência de retenção salva.')}catch(error){toast(error.message)}finally{buttonBusy(b,false)}}}
async function loadOutbox(){if(!user||health?.mode!=='development')return;const requestedUser=user.id;try{const r=await api('/api/dev/outbox');if(!user||user.id!==requestedUser)return;outbox=r.messages||[];$('#devDelivery').classList.remove('hidden');$('#outbox').innerHTML=outbox.length?outbox.map(m=>`<article class="dev-item"><div class="row"><strong>${esc(m.subject||m.kind||'Entrega de desenvolvimento')}</strong><small>${esc(date(m.createdAt))}</small></div><small>Destino: ${esc(m.to)} · ${esc(m.kind)}</small>${m.token?`<code class="token">${esc(m.token)}</code>`:''}${m.code?`<code class="token">${esc(m.code)}</code>`:''}<p style="margin-bottom:0">${esc(m.body||'')}</p>${m.token&&/verif|confirm/i.test(m.kind+' '+m.subject)?`<div class="actions"><button class="outline small" data-outbox-token="${esc(m.id)}">Usar token para confirmar e-mail</button></div>`:''}</article>`).join(''):'<p class="fine">Nenhuma entrega para esta conta.</p>'}catch{outbox=[];$('#devDelivery').classList.add('hidden')}}$('#refreshOutbox').onclick=()=>loadOutbox();
function localDelivery(kind,to,subject=''){if(health?.mode!=='development')return '';const m=outbox.find(m=>m.kind===kind&&(!to||m.to===to)&&(!subject||String(m.subject).includes(subject)));return m?`<div class="flow-note"><b>Entrega local de desenvolvimento, sem envio real</b><br>${esc(m.to)}<code class="token">${esc(m.code||m.token||'Sem código disponível')}</code></div>`:''}
function registerDevice(){if(!isVerified())return toast('Confirme seu e-mail antes de cadastrar um aparelho.');modal(`<div class="eyebrow">CADASTRO AUTORIZADO</div><h2>Um novo Android.</h2><p>Crie uma credencial exclusiva e transfira-a para o aplicativo em seu aparelho. Não compartilhe a credencial com terceiros.</p><form id="registerDeviceForm"><label for="deviceName">Nome do aparelho</label><input id="deviceName" placeholder="Meu Android" maxlength="80" required><label class="checkbox-label"><input required type="checkbox">Este aparelho é meu ou tenho autorização para cadastrá-lo.</label><div class="actions"><button class="primary">Criar credencial ↗</button></div></form><p class="fine">Cadastrar não autoriza bloqueio nem microfone. Essas permissões precisam ser concedidas explicitamente no Android.</p>`);$('#registerDeviceForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;buttonBusy(b,true);try{const r=await api('/api/devices/register',{method:'POST',body:{name:$('#deviceName').value.trim(),platform:'ANDROID'}});await refreshData(false);modal(`<div class="eyebrow">CREDENCIAL INDIVIDUAL</div><h2>${esc(r.device?.name||'Android cadastrado')}.</h2><p>Copie a credencial para o aplicativo nativo. Ela é exibida apenas nesta etapa.</p><label>Identificador do dispositivo</label><code class="token">${esc(r.device?.id)}</code><label>Credencial do dispositivo</label><code class="token">${esc(r.deviceToken)}</code><p class="fine">A credencial permite enviar eventos e receber comandos deste aparelho. Guarde-a apenas no dispositivo autorizado. Se perdida, desconecte o aparelho e gere um novo cadastro.</p><div class="actions"><button class="primary" data-action="close">Entendi, continuar</button></div>`)}catch(error){toast(error.message)}finally{buttonBusy(b,false)}}}
function criticalModal(title,description,onSubmit,extra=''){modal(`<div class="eyebrow">CONFIRMAÇÃO DE IDENTIDADE</div><h2>${esc(title)}</h2><p>${esc(description)}</p><form id="criticalForm">${extra}<label for="confirmPassword">Sua senha atual</label><input id="confirmPassword" type="password" autocomplete="current-password" required><div class="actions"><button class="primary">Confirmar solicitação</button><button class="outline" type="button" data-action="close">Voltar</button></div></form><p class="fine">A ação será validada no servidor e registrada em auditoria.</p>`);$('#criticalForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;buttonBusy(b,true);try{await onSubmit($('#confirmPassword').value);$('#dialog').close();await refreshData(false);await loadOutbox()}catch(error){toast(error.message)}finally{buttonBusy(b,false)}}}
function requestCommand(type,id){if(!isVerified())return toast('Confirme o e-mail antes de enviar ações.');const d=devices.find(d=>d.id===id);if(!d)return toast('Selecione um dispositivo cadastrado.');const extra=type==='LOST'?`<label for="lostMessage">Mensagem para a interface do SENTINELA</label><textarea id="lostMessage" maxlength="180" placeholder="Mensagem de contato do proprietário"></textarea><p class="fine">A tela de bloqueio nativa não será substituída. Não inclua dados sensíveis.</p>`:'';const description=type==='RECOVER'?`Encerrar o estado de proteção do SENTINELA em ${d.name}. O PIN e o bloqueio nativo não serão removidos.`:type==='ALARM'?`Solicitar um alarme sonoro em ${d.name}. O dispositivo pode emitir som quando receber a ação. Evite esta opção em um assalto.`:`Enviar “${commandLabels[type]}” para ${d.name}. O comando ficará pendente até o Android receber e confirmar a operação autorizada.`;criticalModal(commandLabels[type]+'.',description,async password=>{await api(`/api/devices/${encodeURIComponent(id)}/commands`,{method:'POST',body:{type,password,payload:type==='LOST'?{message:$('#lostMessage').value.trim()}:undefined}});toast('Solicitação registrada. Aguarde a confirmação do aparelho em Comandos.');currentPage='commands';selectedDevice=id},extra)}
async function verifyContact(id){const c=contacts.find(contact=>contact.id===id);if(!c)return toast('Contato não encontrado.');try{await api(`/api/contacts/${encodeURIComponent(id)}/request-verification`,{method:'POST',body:{}});await loadOutbox();modal(`<div class="eyebrow">VALIDAÇÃO DE CONTATO</div><h2>Confirme o número.</h2><p>Use o código de uso único gerado pelo backend. No desenvolvimento, consulte a caixa de entrega local.</p>${localDelivery('sms',contacts.find(c=>c.id===id)?.phone)}<form id="verifyContactForm"><label for="phoneCode">Código de confirmação</label><input id="phoneCode" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required><div class="actions"><button class="primary">Validar número</button>${c.email?`<button type="button" class="outline small" data-verify-contact-email="${esc(c.id)}">Validar e-mail</button>`:''}<button class="outline small" data-edit-contact="${esc(c.id)}" type="button">Editar</button><button class="quiet" data-delete-contact="${esc(c.id)}" type="button">Remover</button></div></form><p class="fine">Uma confirmação local valida o fluxo de desenvolvimento; não comprova entrega de SMS no mundo real.</p>`);$('#verifyContactForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;buttonBusy(b,true);try{await api(`/api/contacts/${encodeURIComponent(id)}/verify`,{method:'POST',body:{code:$('#phoneCode').value}});$('#dialog').close();toast('Código validado pelo servidor.');await refreshData()}catch(error){toast(error.message)}finally{buttonBusy(b,false)}}}catch(error){toast(error.message)}}
function emailModal(token=''){modal(`<div class="eyebrow">IDENTIDADE DA CONTA</div><h2>Confirme seu e-mail.</h2><p>Insira o token de uso único recebido pelo transporte configurado. Em desenvolvimento, ele está na caixa local.</p><form id="verifyEmailForm"><label for="emailToken">Token de confirmação</label><input id="emailToken" value="${esc(token)}" autocomplete="off" required><div class="actions"><button class="primary">Confirmar e-mail</button></div></form>`);$('#verifyEmailForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;buttonBusy(b,true);try{await api('/api/auth/verify-email',{method:'POST',body:{token:$('#emailToken').value.trim()}});$('#dialog').close();await loadSession();toast('Token confirmado no ambiente local.')}catch(error){toast(error.message)}finally{buttonBusy(b,false)}}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action],[data-command],[data-disconnect],[data-verify-contact],[data-device-location],[data-revoke-session],[data-delete-locations],[data-outbox-token],[data-verify-contact-email],[data-delete-contact],[data-dev-plan]');if(!b)return;try{if(b.dataset.devPlan){await api('/api/subscription',{method:'PATCH',body:{plan:b.dataset.devPlan}});toast('Plano local alterado para teste de permissões. Nenhuma cobrança.');await refreshData(false)}if(b.dataset.action==='cancelPlan')criticalModal('Cancelar assinatura.','Registrar cancelamento sem desbloquear o telefone nem encerrar emergências.',async password=>{await api('/api/subscription/cancel',{method:'POST',body:{password}});toast('Cancelamento registrado. Estado do aparelho preservado.')});if(b.dataset.action==='primaryPhone')primaryPhoneModal();if(b.dataset.deleteContact)criticalModal('Remover contato.','Este contato deixará de receber novos alertas autorizados.',async password=>{await api(`/api/contacts/${encodeURIComponent(b.dataset.deleteContact)}`,{method:'DELETE',body:{password}});toast('Contato removido.')});if(b.dataset.verifyContactEmail)await contactEmailModal(b.dataset.verifyContactEmail);if(b.dataset.action==='close')$('#dialog').close();if(b.dataset.action==='registerDevice')registerDevice();if(b.dataset.action==='verifyEmail')emailModal();if(b.dataset.action==='requestEmail'){buttonBusy(b,true);try{await api('/api/auth/request-email-verification',{method:'POST',body:{}});await loadOutbox();toast('Novo token gerado. Consulte a caixa de entrega local.')}finally{buttonBusy(b,false)}}if(b.dataset.action==='resetOwnAccount'){await api('/api/auth/request-reset',{method:'POST',body:{email:user.email}});await loadOutbox();toast('Solicitação de recuperação processada. Consulte a entrega local.')}if(b.dataset.command)requestCommand(b.dataset.command,b.dataset.device);if(b.dataset.disconnect)criticalModal('Desconectar aparelho.','A credencial deste dispositivo será revogada. Isso não remove o bloqueio de segurança nativo do telefone.',async password=>{await api(`/api/devices/${encodeURIComponent(b.dataset.disconnect)}`,{method:'DELETE',body:{password}});toast('Dispositivo desconectado e credencial revogada.')});if(b.dataset.verifyContact)await verifyContact(b.dataset.verifyContact);if(b.dataset.deviceLocation){selectedDevice=b.dataset.deviceLocation;currentPage='locations';await renderPage()}if(b.dataset.revokeSession)criticalModal('Encerrar sessão.','Esta sessão perderá o acesso ao painel. Se for a sessão atual, você precisará entrar novamente.',async password=>{await api(`/api/auth/sessions/${encodeURIComponent(b.dataset.revokeSession)}`,{method:'DELETE',body:{password}});toast('Sessão revogada.');await loadSession()});if(b.dataset.deleteLocations)criticalModal('Excluir histórico de localização.','As posições armazenadas deste dispositivo serão removidas do banco. Novas posições só serão recebidas se o Android continuar autorizado.',async password=>{await api(`/api/devices/${encodeURIComponent(b.dataset.deleteLocations)}/locations`,{method:'DELETE',body:{password}});toast('Histórico de posições excluído.')});if(b.dataset.outboxToken){const m=outbox.find(m=>String(m.id)===b.dataset.outboxToken);if(m?.token)emailModal(m.token)}}catch(error){toast(error.message)}});

function primaryPhoneModal(){modal(`<div class="eyebrow">TELEFONE DA CONTA</div><h2>Seu número principal.</h2><p>Cadastre o telefone e confirme o código de uso único. O transporte local não envia SMS real.</p><form id="primaryPhoneForm"><label for="primaryPhone">Telefone com código do país</label><input id="primaryPhone" type="tel" value="${esc(user.phone||'')}" placeholder="+5581999999999" pattern="[+][1-9][0-9]{7,14}" required><div class="actions"><button class="primary">Gerar confirmação</button></div></form>`);$('#primaryPhoneForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/auth/phone/request',{method:'POST',body:{phone:$('#primaryPhone').value.trim()}});await loadOutbox();modal(`<div class="eyebrow">CONFIRMAÇÃO DO TELEFONE</div><h2>Valide seu número.</h2>${localDelivery('sms',null,'primary_phone')}<form id="primaryCodeForm"><label for="primaryCode">Código da entrega local</label><input id="primaryCode" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required><div class="actions"><button class="primary">Confirmar número</button></div></form>`);$('#primaryCodeForm').onsubmit=async ev=>{ev.preventDefault();try{await api('/api/auth/phone/verify',{method:'POST',body:{code:$('#primaryCode').value}});$('#dialog').close();await loadSession();toast('Número principal confirmado no ambiente local.')}catch(error){toast(error.message)}}}catch(error){toast(error.message)}}}
async function contactEmailModal(id){await api(`/api/contacts/${encodeURIComponent(id)}/request-email`,{method:'POST',body:{}});await loadOutbox();modal(`<div class="eyebrow">ENTREGA AUTORIZADA</div><h2>Confirme o e-mail do contato.</h2><p>O contato precisa concordar com o recebimento. No ambiente local, use o token gerado na caixa de entrega, sem envio real.</p>${localDelivery('email',contacts.find(c=>c.id===id)?.email,'contact_email')}<form id="contactEmailForm"><label for="contactEmailToken">Token de uso único</label><input id="contactEmailToken" autocomplete="off" required><div class="actions"><button class="primary">Confirmar e-mail</button></div></form>`);$('#contactEmailForm').onsubmit=async e=>{e.preventDefault();try{await api(`/api/contacts/${encodeURIComponent(id)}/verify-email`,{method:'POST',body:{token:$('#contactEmailToken').value.trim()}});$('#dialog').close();await refreshData(false);toast('Token do contato confirmado pelo servidor.')}catch(error){toast(error.message)}}}

async function init(){renderAuth();try{health=await api('/api/health');const dev=health.mode==='development';$('#environment').textContent=dev?'LOCAL DEV · Dados persistidos':'AMBIENTE REAL';$('#environment').className='pill '+(dev?'warn':'good');if(dev&&health.database!=='sqlite')$('#environment').textContent='LOCAL DEV · '+(health.database||'Banco conectado');await loadSession()}catch(error){$('#environment').textContent='Servidor indisponível';$('#environment').className='pill warn';message(error.message,true)}}init();

function closeMenu(){$('#panelSidebar').classList.remove('menu-open');$('#menuToggle').setAttribute('aria-expanded','false')}
$('#menuToggle').onclick=()=>{const open=$('#panelSidebar').classList.toggle('menu-open');$('#menuToggle').setAttribute('aria-expanded',String(open))};
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
function gotoPage(page){currentPage=page;closeMenu();history.replaceState(null,'','#'+page);renderPage().catch(e=>toast(e.message));window.scrollTo({top:0,behavior:'smooth'})}
function extraPage(page){
 const permissions=devices.map(d=>`<article class="device"><div class="row"><h3>${esc(d.name)}</h3>${tag(d.state)}</div><p class="fine">Última comunicação: ${esc(date(d.lastSeen))}</p><dl class="diagnostic">${Object.entries(d.capabilities||{}).map(([key,value])=>`<div><dt>${esc(key)}</dt><dd>${esc(typeof value==='object'?JSON.stringify(value):String(value))}</dd></div>`).join('')||'<div><dt>Permissions</dt><dd>Nenhuma telemetria recebida</dd></div>'}</dl><button class="outline small" data-device-detail="${esc(d.id)}">Ver detalhes</button></article>`).join('');
 if(page==='protection')return `<section class="protection-summary"><span class="status-dot"></span><div><div class="eyebrow">ESTADO INFORMADO PELOS APARELHOS</div><h2>${devices.filter(d=>d.state==='ACTIVE').length} de ${devices.length} com proteção ativa</h2><p>O estado só muda neste painel quando a telemetria autenticada do Android é recebida.</p></div></section><div class="actions"><button class="outline" data-go="devices">Meus dispositivos</button><button class="outline" data-go="commands">Ações remotas</button></div><section class="section-card"><h3>Permissões e mecanismos disponíveis.</h3><p class="fine">Ative ou desative a proteção no Android cadastrado. O teste de bloqueio exige uma ação explícita e administração autorizada no aparelho.</p><div class="device-list">${permissions||empty('Conecte seu Android.','As permissões serão exibidas depois da primeira sincronização.')}</div></section>`;
 if(page==='voice')return `<section class="section-card" style="margin-top:0"><div class="eyebrow">RECONHECIMENTO NO DISPOSITIVO</div><h2>Uma sessão de cada vez.</h2><p>Configure e teste os comandos no aplicativo Android. O painel web não captura áudio nem mantém o microfone ligado.</p><ul class="checklist"><li>Reconhecimento local, quando suportado pelo aparelho.</li><li>Sessão iniciada por você e encerrada ao sair do aplicativo.</li><li>Frase de voz não autoriza recuperação nem ações críticas da conta.</li></ul><div class="actions"><a class="outline" href="/demo-app.html#voice">Testar experiência DEMO</a><button class="outline" data-go="protection">Consultar permissões</button></div></section><section class="section-card"><h3>Ativações recebidas.</h3>${incidentRows(incidents.filter(i=>/VOICE/i.test(i.type)))}</section>`;
 if(page==='triggers')return `<section class="section-card" style="margin-top:0"><h3>Escolha um acionamento compatível.</h3><div class="capability-row"><div><strong>Botão no aplicativo Android</strong><p class="fine">Ação explícita no aparelho cadastrado, com proteção autorizada.</p></div><span class="state-tag">Implementado no app</span></div><div class="capability-row"><div><strong>Ação na notificação</strong><p class="fine">Disponível enquanto o serviço voluntário estiver ativo.</p></div><span class="state-tag">Condicionado ao Android</span></div><div class="capability-row"><div><strong>Power três vezes / Power + Volume</strong><p class="fine">Sem interceptação disponível. O SENTINELA preserva o SOS nativo do Android.</p></div><span class="pill warn">Não suportado</span></div><a class="outline" href="/demo-app.html#triggers">Simular acionamentos no DEMO</a></section>`;
 if(page==='lost')return `<div class="notice">Os comandos precisam ser recebidos pelo Android e podem expirar. A mensagem aparece dentro do SENTINELA; o bloqueio nativo permanece sob controle do sistema.</div>${devices.length?devices.map(d=>`<article class="device"><div class="row"><h3>${esc(d.name)}</h3>${tag(d.state)}</div><p class="fine">${isOnline(d)?'Comunicação recente':'Offline ou sem comunicação recente'} · ${esc(date(d.lastSeen))}</p><div class="actions"><button class="primary" data-command="LOST" data-device="${esc(d.id)}">Ativar modo perdido</button><button class="outline" data-command="ALARM" data-device="${esc(d.id)}">Solicitar alarme</button><button class="outline" data-command="STOP_ALARM" data-device="${esc(d.id)}">Parar alarme</button><button class="outline" data-command="RECOVER" data-device="${esc(d.id)}">Encerrar modo perdido</button><button class="quiet" data-device-location="${esc(d.id)}">Última localização ↗</button></div></article>`).join(''):empty('Cadastre um Android.','Somente dispositivos autorizados podem receber comandos.')}`;
 if(page==='notifications')return '<div class="loading">Consultando notificações da sua conta…</div>';
 if(page==='profile')return '<div class="loading">Consultando seus dados…</div>';
 if(page==='help')return `<section class="section-card" style="margin-top:0"><h3>Configure com confiança.</h3>${[
 ['Como começar no Android?','Instale o APK de desenvolvimento, configure a URL do backend local e entre com sua conta verificada. Conceda as permissões individualmente, quando desejar testar cada recurso.'],
 ['Como autorizar o bloqueio?','Ative administração do dispositivo pelo diálogo oficial no Android. Configure um PIN nativo primeiro. lockNow depende dessa autorização e não impede desligamento ou chamadas de emergência.'],
 ['Como funciona a localização?','O aparelho captura uma posição pontual após sua permissão e envia ao backend quando autorizado. Sem conexão ou com o telefone desligado, só há a última posição recebida.'],
 ['Como recuperar o celular?','Use uma sessão autenticada, confirme a senha e solicite recuperação. O aparelho precisa receber o comando. Isso encerra o estado do SENTINELA, sem remover o PIN nativo.'],
 ['O DEMO envia alertas ou bloqueia o aparelho?','Não. A demonstração possui dados fictícios e estado local isolado. Ela não acessa GPS, microfone, contas nem APIs reais.'],
 ['Privacidade e retenção','Você controla a retenção das posições e pode excluir o histórico em Segurança. Alertas dependem do consentimento e das verificações do contato. Não há gravação contínua de conversas.'],
 ['Termos desta versão','Versão de desenvolvimento para testes autorizados. Não substitui serviços de emergência, mecanismos nativos ou garantia de recuperação. Cobranças, infraestrutura e provedores ainda dependem de configuração e validação.']
 ].map(([q,a])=>`<details class="faq"><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><section class="section-card"><h3>Diagnóstico técnico.</h3><dl class="diagnostic"><div><dt>Backend</dt><dd>${esc(health?.mode||'Indisponível')}</dd></div><div><dt>Banco</dt><dd>${esc(health?.database||'Não informado')}</dd></div><div><dt>E-mail</dt><dd>${esc(health?.emailTransport||'Não informado')}</dd></div><div><dt>SMS</dt><dd>${esc(health?.smsTransport||'Não informado')}</dd></div><div><dt>Cobrança</dt><dd>${health?.billingConfigured?'Configurada':'Não configurada'}</dd></div></dl><p class="fine">SENTINELA · Desenvolvido por unitrixapp. Sem validação de hardware por este painel.</p></section>`;
 return empty('Página não encontrada.','Escolha uma área no menu.','<button class="outline" data-go="overview">Voltar ao início</button>');
}
function wireExtra(){if($('#incidentSearch')){const filter=()=>{$('#incidentResults').innerHTML=incidentRows(incidents.filter(i=>(!$('#incidentState').value||i.state===$('#incidentState').value)&&`${i.type} ${deviceName(i.deviceId)}`.toLocaleLowerCase('pt-BR').includes($('#incidentSearch').value.toLocaleLowerCase('pt-BR'))))};$('#incidentSearch').oninput=filter;$('#incidentState').onchange=filter}}
async function loadProfile(){try{const r=await api('/api/profile');if(currentPage!=='profile')return;const p={...(r.user||r.profile||r),secondaryPhone:r.secondaryPhone??r.user?.secondaryPhone,avatar:r.avatar??r.user?.avatar};$('#content').innerHTML=`<div class="split"><section class="section-card" style="margin-top:0"><h3>Dados pessoais.</h3><form id="profileForm"><label for="profileName">Nome</label><input id="profileName" value="${esc(p.name||user.name)}" maxlength="80" required><label for="secondaryPhone">Telefone secundário</label><input id="secondaryPhone" type="tel" value="${esc(p.secondaryPhone||'')}" maxlength="30"><label for="profileAvatar">Iniciais do avatar</label><input id="profileAvatar" value="${esc(p.avatar||'')}" maxlength="8" placeholder="LP"><div class="actions"><button class="primary">Salvar dados</button></div></form></section><section class="section-card" style="margin-top:0"><h3>Identidade e acesso.</h3><p>${esc(user.email)}</p><span class="pill ${isVerified()?'good':'warn'}">E-mail ${isVerified()?'confirmado':'pendente'}</span><p style="margin-top:16px">${esc(user.phone||'Telefone principal não cadastrado')}</p><div class="actions"><button class="outline" data-action="primaryPhone">Configurar telefone</button><button class="outline" data-go="security">Sessões e privacidade</button></div><hr class="profile-divider"><h3>Seus dados.</h3><p class="fine">Exporte uma cópia ou exclua sua conta e os dados armazenados no backend local.</p><div class="actions"><button class="outline" data-privacy="export">Exportar dados</button><button class="quiet" data-privacy="delete">Excluir conta</button></div></section></div>`;$('#profileForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;buttonBusy(b,true);try{await api('/api/profile',{method:'PATCH',body:{name:$('#profileName').value.trim(),secondaryPhone:$('#secondaryPhone').value.trim(),avatar:$('#profileAvatar').value.trim()}});await loadSession();toast('Dados pessoais salvos.')}catch(error){toast(error.message)}finally{buttonBusy(b,false)}}}catch(error){if(currentPage==='profile')$('#content').innerHTML=empty('Perfil indisponível.',error.message)}}
async function loadNotifications(){try{const r=await api('/api/notifications');if(currentPage!=='notifications')return;const list=r.notifications||[];$('#content').innerHTML=`<div class="section-heading"><p class="fine">Alertas registrados pelo backend da sua conta.</p><button class="outline small" data-read-all>Marcar todas como lidas</button></div><section class="section-card" style="margin-top:0">${list.length?list.map(n=>`<article class="activity"><div><strong>${esc(n.title||n.type||'Notificação')}</strong><p class="fine">${esc(n.body||n.message||'')}</p><small>${esc(date(n.createdAt))}</small></div><div>${n.read||n.readAt?'<span class="pill">Lida</span>':`<button class="outline small" data-read="${esc(n.id)}">Marcar como lida</button>`}</div></article>`).join(''):empty('Tudo em dia.','Novos alertas aparecerão aqui quando forem registrados pelo backend.')}</section>`}catch(error){if(currentPage==='notifications')$('#content').innerHTML=empty('Notificações indisponíveis.',error.message)}}
function deviceDetail(id){const d=devices.find(d=>d.id===id);if(!d)return;modal(`<div class="eyebrow">DISPOSITIVO AUTORIZADO</div><h2>${esc(d.name)}</h2>${tag(d.state)}<dl class="diagnostic"><div><dt>Última atividade</dt><dd>${esc(date(d.lastSeen))}</dd></div><div><dt>Conexão</dt><dd>${isOnline(d)?'Recente':'Sem sinal recente'}</dd></div><div><dt>Plataforma</dt><dd>${esc(d.platform)}</dd></div>${Object.entries(d.capabilities||{}).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(String(v))}</dd></div>`).join('')}</dl><form id="renameDeviceForm"><label for="renameDevice">Nome do dispositivo</label><input id="renameDevice" value="${esc(d.name)}" maxlength="80" required><div class="actions"><button class="primary">Salvar nome</button></div></form><h3 style="margin-top:24px">Histórico individual.</h3>${incidentRows(incidents.filter(i=>i.deviceId===id).slice(0,8))}`);$('#renameDeviceForm').onsubmit=async e=>{e.preventDefault();try{await api(`/api/devices/${encodeURIComponent(id)}`,{method:'PATCH',body:{name:$('#renameDevice').value.trim()}});$('#dialog').close();await refreshData(false);toast('Nome do dispositivo atualizado.')}catch(error){toast(error.message)}}}
function editContact(id){const c=contacts.find(c=>c.id===id);if(!c)return;modal(`<h2>Editar contato.</h2><form id="editContactForm"><label for="editName">Nome</label><input id="editName" value="${esc(c.name)}" maxlength="80" required><label for="editPhone">Telefone</label><input id="editPhone" type="tel" value="${esc(c.phone)}" maxlength="30" required><label for="editEmail">E-mail</label><input id="editEmail" type="email" value="${esc(c.email||'')}"><label class="checkbox-label"><input id="editAlerts" type="checkbox" ${c.allowAlerts?'checked':''}>O contato concorda em receber alertas.</label><p class="fine">Alterar telefone ou e-mail exige nova confirmação do dado alterado.</p><div class="actions"><button class="primary">Salvar contato</button></div></form>`);$('#editContactForm').onsubmit=async e=>{e.preventDefault();try{await api(`/api/contacts/${encodeURIComponent(id)}`,{method:'PATCH',body:{name:$('#editName').value.trim(),phone:$('#editPhone').value.trim(),email:$('#editEmail').value.trim(),allowAlerts:$('#editAlerts').checked}});$('#dialog').close();await refreshData(false);toast('Contato atualizado.')}catch(error){toast(error.message)}}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-go],[data-device-detail],[data-edit-contact],[data-incident],[data-read],[data-read-all]');if(!b)return;try{if(b.dataset.go){$('#dialog').close();gotoPage(b.dataset.go)}if(b.dataset.deviceDetail)deviceDetail(b.dataset.deviceDetail);if(b.dataset.editContact)editContact(b.dataset.editContact);if(b.hasAttribute('data-read-all')){await api('/api/notifications/read-all',{method:'POST',body:{}});await loadNotifications();toast('Notificações marcadas como lidas.')}if(b.dataset.read){await api(`/api/notifications/${encodeURIComponent(b.dataset.read)}`,{method:'PATCH',body:{read:true}});await loadNotifications()}if(b.dataset.incident){const r=await api(`/api/incidents/${encodeURIComponent(b.dataset.incident)}`),i=r.incident||r;modal(`<div class="eyebrow">EVENTO RECEBIDO DO DISPOSITIVO</div><h2>${esc(i.type||'Incidente')}</h2>${tag(i.state)}<p style="margin-top:20px">${esc(deviceName(i.deviceId))} · ${esc(date(i.createdAt))}</p><h3>Dados registrados.</h3><pre class="token">${esc(typeof i.details==='string'?i.details:JSON.stringify(i.details||{},null,2))}</pre>${r.location?`<h3>Localização associada.</h3><p class="fine">${esc(r.location.latitude)}, ${esc(r.location.longitude)} · ${esc(Math.round(r.location.accuracy||0))} m · ${esc(date(r.location.capturedAt||r.location.createdAt))}</p>`:'<p class="fine">Nenhuma localização associada a este registro.</p>'}<h3>Comandos relacionados.</h3>${r.commands?.length?r.commands.map(c=>`<div class="activity"><div><strong>${esc(commandLabels[c.type]||c.type)}</strong><small>${esc(date(c.createdAt))}</small></div>${tag(c.status)}</div>`).join(''):'<p class="fine">Nenhum comando relacionado registrado.</p>'}<p class="fine">O registro descreve a telemetria recebida; não comprova sozinho a execução física. A associação temporal não prova que um comando causou este evento.</p><button class="outline" data-go="commands">Consultar comandos</button>`)}}catch(error){toast(error.message)}});

document.addEventListener('click',e=>{const b=e.target.closest('[data-privacy]');if(!b)return;if(b.dataset.privacy==='export')criticalModal('Exportar seus dados.','Gerar uma cópia dos dados da sua conta, sem credenciais ou tokens de acesso.',async password=>{const data=await api('/api/account/export',{method:'POST',body:{password}});const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='sentinela-meus-dados.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exportação gerada. Guarde sua cópia em um local seguro.')});if(b.dataset.privacy==='delete')criticalModal('Excluir sua conta.','Esta ação remove sua conta e os dados do backend, revoga as credenciais dos dispositivos e encerra suas sessões. O PIN nativo do Android permanece inalterado.',async password=>{await api('/api/account',{method:'DELETE',body:{password,confirmation:$('#deleteConfirmation').value}});user=null;csrf='';devices=[];contacts=[];incidents=[];events=[];outbox=[];showAuth();toast('Conta e dados locais excluídos.');},'<label for="deleteConfirmation">Digite EXCLUIR para confirmar</label><input id="deleteConfirmation" autocomplete="off" pattern="EXCLUIR" required>')});
